import{_ as d,o as r,c as a,a2 as e}from"./chunks/framework.CqpfiAoK.js";const b=JSON.parse('{"title":"শব্দভাণ্ডার অভিধান","description":"","frontmatter":{},"headers":[],"relativePath":"bn/90-术语词典.md","filePath":"bn/90-术语词典.md","lastUpdated":null}'),o={name:"bn/90-术语词典.md"};function l(n,t,h,i,u,_){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="শব্দভাণ্ডার-অভিধান" tabindex="-1">শব্দভাণ্ডার অভিধান <a class="header-anchor" href="#শব্দভাণ্ডার-অভিধান" aria-label="Permalink to &quot;শব্দভাণ্ডার অভিধান&quot;">​</a></h1><table tabindex="0"><thead><tr><th>আইটেম</th><th>বিষয়বস্তু</th></tr></thead><tbody><tr><td>নথি নম্বর</td><td>90</td></tr><tr><td>মডিউল</td><td>পরিশিষ্ট ও রেফারেন্স উপাদান</td></tr><tr><td>মূল কীওয়ার্ড</td><td>শব্দভাণ্ডার অভিধান, মূল ধারণা, সংজ্ঞা, ঐক্যকৃত শব্দভাণ্ডার, Hengyuanzhou</td></tr></tbody></table><h2 id="_1-শব্দভাণ্ডার-ব্যাখ্যা" tabindex="-1">1. শব্দভাণ্ডার ব্যাখ্যা <a class="header-anchor" href="#_1-শব্দভাণ্ডার-ব্যাখ্যা" aria-label="Permalink to &quot;1. শব্দভাণ্ডার ব্যাখ্যা&quot;">​</a></h2><p>এই অভিধানে অ্যাঙ্কর সিম্বায়োসিস সভ্যতার সেটআপ সিস্টেমের মূল শব্দভাণ্ডার সংগ্রহ করা হয়েছে, যার লক্ষ্য সমস্ত নথিতে শব্দভাণ্ডার ব্যবহারকে ঐক্যকৃত করা এবং ধারণার প্রকাশের ধারাবাহিকতা ও নির্ভুলতা নিশ্চিত করা। সমস্ত শব্দভাণ্ডার চীনা ব্যঞ্জনবর্ণের প্রথম অক্ষর অনুযায়ী সাজানো হয়েছে, এবং প্রতিটি শব্দভাণ্ডারে শব্দভাণ্ডারের নাম, ইংরেজি রেফারেন্স নাম (যদি থাকে), সংজ্ঞা ও সংক্ষিপ্ত ব্যাখ্যা অন্তর্ভুক্ত। এই অভিধানটি একটি গতিশীল আপডেট নথি, এবং সেটআপ সিস্টেমের সম্প্রসারণের সাথে সাথে নতুন শব্দভাণ্ডার ক্রমাগত যোগ করা হবে।</p><h2 id="_2-মূল-শব্দভাণ্ডার-তালিকা" tabindex="-1">2. মূল শব্দভাণ্ডার তালিকা <a class="header-anchor" href="#_2-মূল-শব্দভাণ্ডার-তালিকা" aria-label="Permalink to &quot;2. মূল শব্দভাণ্ডার তালিকা&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ক্রম</th><th>শব্দভাণ্ডার</th><th>সংজ্ঞা ও ব্যাখ্যা</th></tr></thead><tbody><tr><td>1</td><td>অ্যাঙ্কর</td><td>আইনি নেটওয়ার্কের স্থিতিশীল নোড, যা তলের আইনির স্থিতিশীলতা বজায় রাখা, আন্তঃ-তল সংযোগ বাস্তবায়ন এবং সময় প্রত্যাবর্তনের স্থানাঙ্ক মানদণ্ড। অ্যাঙ্কর মূলত মহাজাগতিক মূল আইনির নির্দিষ্ট স্থানিক অবস্থানে উচ্চ-ঘনত্বের সংঘটন, এবং এটি স্ব-বজায় রাখা ও অ্যালাইনমেন্ট ক্ষমতা রাখে।</td></tr><tr><td>2</td><td>অ্যাঙ্কর সিম্বায়োসিস সভ্যতা</td><td>অ্যাঙ্কর প্রক্রিয়াকে প্রযুক্তিগত ভিত্তি হিসেবে এবং সিম্বায়োসিস বিবর্তনকে মূল দর্শন হিসেবে নেওয়া সভ্যতার রূপ। এটি লুঠমূলক সাধন ব্যবস্থার বিরোধিতা করে, এবং ভাগ্য ও বিবর্তনের পছন্দের অধিকার সব প্রাণীর কাছে ফিরিয়ে দেওয়ার পক্ষপাতী, এবং বেশি কাজে বেশি লাভ, স্ব-জন্ম ও স্ব-বৃদ্ধি, সবার পথ থাকা, সব জাতির সহযোগী অগ্রগতি বাস্তবায়ন করে।</td></tr><tr><td>3</td><td>Hengyuanzhou</td><td>&quot;ওয়ানলিং হেঙমাও বেনইউয়ান ঝোউ&quot; এর সংক্ষিপ্ত রূপ, যা অ্যাঙ্কর সিম্বায়োসিস সভ্যতা বসবাস ও শাসন করে এমন মহাজাগতিক সমগ্র অঞ্চল। এটি পদার্থ তল, শক্তি স্তর, চেতনা অঞ্চল ও আইনি নেটওয়ার্ক চারটি স্তর দ্বারা গঠিত যৌগিক অস্তিত্ব।</td></tr><tr><td>4</td><td>ওয়ানলিং হেঙমাও বেনইউয়ান ঝোউ</td><td>Hengyuanzhou এর পূর্ণ নাম। &quot;ওয়ানলিং&quot; বলতে বোঝায় সকল প্রাণী যারা উপলব্ধি ও বিবর্তনের সম্ভাবনা রাখে, &quot;হেঙমাও&quot; বলতে বোঝায় মহাজাগতিক ভারসাম্য বজায় রাখা অ্যাঙ্কর প্রক্রিয়া, &quot;বেনইউয়ান ঝোউ&quot; মূল আইনিকে ভিত্তি হিসেবে এবং সিম্বায়োসিস বিবর্তনকে দিকনির্দেশ হিসেবে নেওয়া মূল বৈশিষ্ট্যকে জোর দেয়।</td></tr><tr><td>5</td><td>সিম্বায়োসিস</td><td>অ্যাঙ্কর সিম্বায়োসিস সভ্যতার মূল দর্শনগুলির মধ্যে একটি, যা বিভিন্ন জীবিত ব্যক্তি, জাতি ও সভ্যতার মধ্যে পারস্পরিক লাভজনক সহযোগিতার মাধ্যমে সহযোগী বিবর্তন বাস্তবায়নকে বোঝায়, অন্যের উৎসে লুঠমূলক বিবর্তনের বিপরীতে।</td></tr><tr><td>6</td><td>লুঠমূলক সাধন ব্যবস্থা</td><td>দুর্বলদের শক্তি, ভাগ্য এমনকি মূল উৎস গ্রাস করার মাধ্যমে নিজের বিবর্তন বাস্তবায়ন করা সাধন পদ্ধতি। এটি অ্যাঙ্কর সিম্বায়োসিস সভ্যতা দ্বারা দৃঢ়ভাবে বিরোধিতা করা ব্যবস্থার ধরন, এবং এটি মহাজাগতিক এনট্রপি ত্বরান্বিতকরণ ও সভ্যতার বিভাজন ঘন ঘন হওয়ার মূল কারণ হিসেবে বিবেচিত।</td></tr><tr><td>7</td><td>তিনশত সেট মূল সাধন ব্যবস্থা</td><td>মহাজাগতিক মূল আইনি থেকে সরাসরি নিষ্কাশিত, অ্যাঙ্কর দ্বারা যাচাইকৃত আধিকারিক সাধন পথ, মোট তিনশত সেট, যা মূল ডিডাকশন ধরন, জীবন চক্র ধরন, স্থান আইনি ধরন, চেতনা উন্নয়ন ধরন, সিম্বায়োসিস নেটওয়ার্ক ধরন, প্রয়োগ ইঞ্জিনিয়ারিং ধরন ছয়টি ধরনে বিভক্ত, প্রতিটি ধরনে পঞ্চাশ সেট।</td></tr><tr><td>8</td><td>মূল তিনটি ভিত্তি</td><td>তিনশত সেট ব্যবস্থার প্রথম তিনটি ভিত্তিগত ব্যবস্থা — ডিডাকশন পুনরাবৃত্তি ব্যবস্থা (1ম সেট), জীবন চক্র ব্যবস্থা (2য় সেট), স্থান আইনি নিয়ন্ত্রণ ব্যবস্থা (3য় সেট), যা অন্য সব ব্যবস্থার সাধনের ভিত্তি।</td></tr><tr><td>9</td><td>ডিডাকশন পুনরাবৃত্তি ব্যবস্থা</td><td>1ম সেট মূল সাধন ব্যবস্থা, যার মূল বৈশিষ্ট্য হলো শতগুণ সাধন ডিডাকশন বৃদ্ধি, এবং এটি বেস্ট ফ্রুটের প্রযুক্তিগত প্রয়োগের মাধ্যমে ডিডাকশন ক্ষমতাকে শতগুণ বাড়ায়, এবং ডিডাকশন, যাচাই, পুনরাবৃত্তির মাধ্যমে সাধন পথ অপ্টিমাইজ করার উপর জোর দেয়।</td></tr><tr><td>10</td><td>জীবন চক্র ব্যবস্থা</td><td>2য় সেট মূল সাধন ব্যবস্থা, যার মূল হলো জীবন শক্তির ভালো চক্র, এবং এটি জোর দেয় যে সাধকের নিজের ও পরিবেশের মধ্যে শক্তি বিনিময় অবশ্যই চক্রাকার হতে হবে, লুঠমূলক নয়।</td></tr><tr><td>11</td><td>স্থান আইনি নিয়ন্ত্রণ ব্যবস্থা</td><td>3য় সেট মূল সাধন ব্যবস্থা, যার মূল হলো স্থান আইনির বোঝাপড়া ও নিয়ন্ত্রণ, এবং এটি আন্তঃ-তল মিথস্ক্রিয়া, বিচ্ছিন্ন স্থান নির্মাণ, কপি মিরর প্রযুক্তি ইত্যাদি গুরুত্বপূর্ণ প্রয়োগের সাধনের ভিত্তি।</td></tr><tr><td>12</td><td>বেস্ট ফ্রুট</td><td>ওয়ান পিস বিশ্ব থেকে আসা বেস্ট ফ্রুট, যা Hengyuanzhou এ প্রযুক্তিগতভাবে প্রয়োগ করা হয়, এবং এটি সাধকের ডিডাকশন ক্ষমতাকে শতগুণ বাড়াতে সক্ষম, এবং এটি ডিডাকশন পুনরাবৃত্তি ব্যবস্থার মূল সহায়ক সরঞ্জাম। শুরুর বাফগুলির মধ্যে একটি।</td></tr><tr><td>13</td><td>যৌথ উৎপাদন চুক্তি প্রক্রিয়া</td><td>অ্যাঙ্কর সিম্বায়োসিস সভ্যতার সম্পদ বণ্টন প্রক্রিয়া, যা মহাজাগতিক সাধন সম্পদকে &quot;চুক্তি&quot; পদ্ধতিতে ব্যক্তি বা গোষ্ঠীর কাছে বণ্টন করে, এবং চুক্তিকারী শ্রম ও অবদানের মাধ্যমে সম্পদের ব্যবহারের অধিকার পায়, এবং বেশি কাজে বেশি লাভ বাস্তবায়ন করে।</td></tr><tr><td>14</td><td>20% সক্রিয়করণ কৌশল</td><td>অ্যাঙ্কর সিম্বায়োসিস সভ্যতার পর্যায়ক্রমিক কৌশলগত লক্ষ্য, প্রথম দিকে সমগ্র মহাজাগতিক 20% প্রাণীকে তলের সর্বোচ্চ শক্তিশালী ব্যক্তি হিসেবে সক্রিয় করা, এবং তাদেরকে অস্থি হিসেবে বাকি 80% প্রাণীর সহযোগী বিবর্তনকে ত্বরান্বিত করা।</td></tr><tr><td>15</td><td>তলের সর্বোচ্চ শক্তিশালী ব্যক্তি</td><td>সাধন অত্যন্ত উচ্চ স্তরে পৌঁছেছে, এবং একা একটি তলের আইনির স্থিতিশীলতা বজায় রাখতে সক্ষম শক্তিশালী ব্যক্তি। এটি 20% সক্রিয়করণ কৌশলের লক্ষ্য প্রশিক্ষণ বস্তু, এবং এটি অ্যাঙ্কর নেটওয়ার্কের গুরুত্বপূর্ণ রক্ষণাবেক্ষণ শক্তি।</td></tr><tr><td>16</td><td>আইনি নেটওয়ার্ক</td><td>Hengyuanzhou এর কাঠামোর চতুর্থ স্তর, যা মহাজাগতিক মূল আইনির চলমান নিম্নস্তর এবং অ্যাঙ্করের মূল স্তর। আইনি নেটওয়ার্ক সমগ্র মহাজাগতিক জুড়ে ছড়িয়ে আছে, এবং এটি সব আইনি অপারেশন (স্থান নিয়ন্ত্রণ, সময় প্রত্যাবর্তন, শক্তি রূপান্তর সহ) এর প্রযুক্তিগত ভিত্তি।</td></tr><tr><td>17</td><td>তল</td><td>অপেক্ষাকৃত স্থিতিশীল আইনি সেট দ্বারা সংজ্ঞায়িত, স্বাধীন স্থান-কাল ধারাবাহিকতা সম্পন্ন অস্তিত্ব অঞ্চল। প্রতিটি তলের স্বতন্ত্র পদার্থিক ধ্রুবক, শক্তি ঘনত্ব, সময় প্রবাহের গতি ও চেতনা সক্রিয়তা রয়েছে।</td></tr><tr><td>18</td><td>আইনি বাধা</td><td>সংলগ্ন তলগুলিকে আলাদা করা আইনি বাধা, যার শক্তি সংলগ্ন তলগুলির মধ্যে আইনি প্যারামিটারের পার্থক্যের মাত্রার উপর নির্ভর করে। তল অতিক্রমের জন্য আইনি বাধা অতিক্রম করতে হয়।</td></tr><tr><td>19</td><td>আইনি ফিঙ্গারপ্রিন্ট</td><td>প্রতিটি তলের মূল আইনি প্যারামিটার হ্যাশ অপারেশনের মাধ্যমে তৈরি করা অনন্য শনাক্তকারী, যার দৈর্ঘ্য 128 বিট, এবং এটি তলের স্থানাঙ্ক সিস্টেমের মূল প্যারামিটারগুলির মধ্যে একটি।</td></tr><tr><td>20</td><td>আগে পর্যবেক্ষণ তারপর সীমিত হস্তক্ষেপ</td><td>সময় প্রত্যাবর্তন ও আন্তঃ-তল প্রত্নতত্ত্বের প্রধান অপারেশন নীতি, যা দাবি করে যে কোনো প্রত্যাবর্তন বা প্রত্নতত্ত্ব অবশ্যই আগে বিশুদ্ধ পর্যবেক্ষণ পর্যায় সম্পন্ন করতে হবে, এবং কোনো বড় ঝুঁকি নেই বলে নিশ্চিত হওয়ার পরেই সীমিত হস্তক্ষেপ করা যাবে।</td></tr><tr><td>21</td><td>কপি মিরর</td><td>স্থান আইনি আইনির উপর ভিত্তি করে উচ্চ-নির্ভুলতা কপি ডিভাইস, যা মূল বস্তুর সংস্পর্শে না এসেই লক্ষ্য অঞ্চলের 1:1 সম্পূর্ণ কপি করতে সক্ষম, এবং এটি অন্য জায়গায় প্রত্নতত্ত্ব পরিকল্পনার মূল সরঞ্জাম।</td></tr><tr><td>22</td><td>বিচ্ছিন্ন স্থান</td><td>স্থান আইনি নিয়ন্ত্রণ প্রযুক্তির মাধ্যমে নির্মিত স্বাধীন আইনি অঞ্চল, যা প্রত্নতত্ত্ব কপি বহন করতে এবং প্রত্নতত্ত্ব কর্মীদের কর্মস্থল হিসেবে ব্যবহৃত হয়, এবং এটি বাহ্যিক মহাজাগতিক থেকে আইনি বাধা দ্বারা সম্পূর্ণরূপে আলাদা।</td></tr><tr><td>23</td><td>শুধুমাত্র জ্ঞান ফেরত</td><td>প্রত্নতত্ত্ব চুক্তির মূল নীতি, যা বোঝায় যে প্রত্নতত্ত্ব প্রক্রিয়ায় লক্ষ্য বস্তু থেকে যা পাওয়া যায় তা শুধুমাত্র বিমূর্ত জ্ঞান ও তথ্য হতে পারে, এবং কোনো পদার্থ, শক্তি বা জীবিত বস্তু ফেরত দেওয়া যাবে না।</td></tr><tr><td>24</td><td>তথ্য বিশুদ্ধকরণ</td><td>মূল তথ্যে বহন করা উৎস তলের আইনি ছাপকে সম্পূর্ণরূপে বিচ্ছিন্ন করা, শুধুমাত্র বিশুদ্ধ অর্থের বিষয়বস্তু রাখা প্রযুক্তিগত প্রক্রিয়া, যা ফেরত দেওয়া জ্ঞানের নিরাপত্তা নিশ্চিত করার মূল অংশ।</td></tr><tr><td>25</td><td>সময় প্যারাডক্স</td><td>সময় প্রত্যাবর্তন অপারেশনে হস্তক্ষেপের আচরণের ফলে কার্য-কারণ যুক্তিতে স্ব-বিরোধী ঘটনা দেখা দেওয়া, যার মধ্যে পিতামহ হত্যা প্যারাডক্স, তথ্য প্যারাডক্স, স্বতন্ত্রতা প্যারাডক্স ও ঘটনা প্যারাডক্স চারটি বড় ধরন অন্তর্ভুক্ত।</td></tr><tr><td>26</td><td>কার্য-কারণ শৃঙ্খলা</td><td>ঘটনাগুলির মধ্যে পূর্বকারণ ও পরবর্তী ফলাফলের ক্রমাগত রৈখিক কাঠামো, যা সময় আইনির মূল ধারণা। সময় প্রত্যাবর্তন অপারেশনের মূল ঝুঁকি হলো কার্য-কারণ শৃঙ্খলার ব্যাঘাত।</td></tr><tr><td>27</td><td>সিম্বায়োসিস সংবিধান</td><td>অ্যাঙ্কর সিম্বায়োসিস সভ্যতার মূল আইন, যার সর্বোচ্চ আইনি কার্যকারিতা রয়েছে, এবং এটি লুঠ-বিরোধী, সিম্বায়োসিস প্রচারের সভ্যতার রঙ ও সাতটি সংবিধান মূল নীতি প্রতিষ্ঠা করেছে।</td></tr><tr><td>28</td><td>সব জাতির সমানতা</td><td>সিম্বায়োসিস সংবিধানের সাতটি মূল নীতির মধ্যে একটি, যা বোঝায় যে সকল জীবিত রূপ তার জাতি, সাধনের মাত্রা, জন্ম নির্বিশেষে আইনের সামনে সমান।</td></tr><tr><td>29</td><td>অদ্ভুত জীবন</td><td>স্বাভাবিক জীবনের সংজ্ঞা মেনে না চলা, বিশেষ অস্তিত্ব রূপ সম্পন্ন জীবন রূপ, যাকে তিনটি প্রকারের মানকীকৃত ব্যবস্থাপনা প্রক্রিয়া অনুসরণ করে শনাক্ত ও ব্যবস্থাপনা করতে হয়।</td></tr><tr><td>30</td><td>অদ্ভুত শক্তি</td><td>স্বাভাবিক শক্তির শ্রেণীবিভাগ মেনে না চলা, বিশেষ বৈশিষ্ট্য ও আচরণ পদ্ধতি সম্পন্ন শক্তি রূপ, যাকে তিনটি প্রকারের মানকীকৃত ব্যবস্থাপনা প্রক্রিয়া অনুসরণ করে শ্রেণীবিভাগ ও নিয়ন্ত্রণ করতে হয়।</td></tr><tr><td>31</td><td>অন্ধকার প্রতিস্থাপন সত্তা</td><td>একটি বিশেষ জীবন রূপ, যা দ্বৈত আত্মার সহাবস্থানের নৈতিক সমস্যা জড়িত, এবং এটি দ্বৈত আত্মার নৈতিক নীতি ও চারটি প্রকারের শাখা ব্যবস্থাপনা নিয়ম অনুসরণ করে ব্যবস্থাপনা করতে হয়।</td></tr><tr><td>32</td><td>দ্বৈত আত্মার নৈতিকতা</td><td>অন্ধকার প্রতিস্থাপন সত্তায় দুটি আত্মার সহাবস্থানের অবস্থার জন্য নৈতিক নীতি, যার মূল হলো দুটি আত্মার নিজের অধিকারকে সম্মান করা, এবং জোরপূর্বক সংমিশ্রণ বা যেকোনো এক পক্ষকে নষ্ট করা নিষিদ্ধ।</td></tr><tr><td>33</td><td>পাঁচ ধরনের সিম্বায়োসিস সভ্যতার প্রকারভেদ</td><td>বাস্তব বিশ্বের সভ্যতার বৈশিষ্ট্যের উপর ভিত্তি করে বিভক্ত পাঁচ ধরনের সিম্বায়োসিস সামাজিক প্রকার: পূর্ব এশিয়ার নিবিড় প্রকার, উত্তর ইউরোপের কল্যাণ প্রকার, উত্তর আমেরিকার বহুমুখী প্রকার, ইউরোপীয় মহাদেশের সামাজিক প্রকার, উন্নয়নশীল প্রকার।</td></tr><tr><td>34</td><td>চার পর্যায়ের উন্নয়ন পথ</td><td>Hengyuanzhou মহাজাগতিকের সমগ্র উন্নয়নের চার পর্যায়ের পথ: বাস্তব ভিত্তি প্রস্তুত → প্রযুক্তি ক্ষমতায়ন → চেতনা বিবর্তন → আন্তঃতারকা সিম্বায়োসিস।</td></tr><tr><td>35</td><td>বাস্তবকে ভিত্তি হিসেবে</td><td>অ্যাঙ্কর সিম্বায়োসিস সভ্যতার মূল অবস্থানগুলির মধ্যে একটি, যা বোঝায় যে বাস্তব বিশ্বই একমাত্র বাস্তব বিশ্ব, উপন্যাসের বিশ্ব হলো মিথ্যা চিন্তা পরীক্ষা, কাল্পনিক বস্তু বাস্তব দিয়ে পরিপূরক করা হয় না, এবং বাস্তবে যা নেই তা নিয়মের ভিত্তিতে আপগ্রেড ও সৃষ্টি করা হয়।</td></tr><tr><td>36</td><td>সিম্বায়োসিস ডিগ্রি</td><td>একটি সভ্যতা বা ব্যক্তির সিম্বায়োসিস নেটওয়ার্কের সাথে মিশ্রণের মাত্রা মূল্যায়ন করার পরিমাণগত সূচক, যা সম্পদ ভাগাভাগির মাত্রা, সহযোগিতার ফ্রিকোয়েন্সি, পরোপকারী আচরণের অনুপাত ইত্যাদি বহু মাত্রা অন্তর্ভুক্ত করে।</td></tr><tr><td>37</td><td>অ্যাঙ্কর কাউন্সিল</td><td>অ্যাঙ্কর সিম্বায়োসিস সভ্যতার সর্বোচ্চ ক্ষমতার প্রতিষ্ঠান, যা সব জাতির প্রতিনিধি অনুপাত অনুযায়ী গঠিত, এবং এটি আইন প্রণয়নের ক্ষমতা ও গুরুত্বপূর্ণ বিষয়ে সিদ্ধান্ত নেওয়ার ক্ষমতা প্রয়োগ করে।</td></tr><tr><td>38</td><td>সিম্বায়োসিস কার্যকরী কমিটি</td><td>অ্যাঙ্কর সিম্বায়োসিস সভ্যতার সর্বোচ্চ প্রশাসনিক প্রতিষ্ঠান, যা সংবিধান ও আইনের কার্যকরীকরণ, দৈনন্দিন শাসনের জন্য দায়ী।</td></tr><tr><td>39</td><td>সিম্বায়োসিস আদালত</td><td>অ্যাঙ্কর সিম্বায়োসিস সভ্যতার সর্বোচ্চ বিচারিক প্রতিষ্ঠান, যা স্বাধীনভাবে বিচারের ক্ষমতা প্রয়োগ করে, এবং অসাংবিধানিক পরীক্ষা ও গুরুত্বপূর্ণ মামলার বিচারের জন্য দায়ী।</td></tr><tr><td>40</td><td>তল ব্যবস্থাপনা ব্যুরো</td><td>অ্যাঙ্কর কাউন্সিলের অধীনস্থ বিশেষ প্রতিষ্ঠান, যা তলের স্থানাঙ্ক মূল ভাণ্ডার রক্ষণাবেক্ষণ, অতিক্রম অনুমতি অনুমোদন, আন্তঃ-তল প্রত্নতত্ত্ব ব্যবস্থাপনা ইত্যাদি বিষয়ের জন্য দায়ী।</td></tr></tbody></table><h2 id="_3-শব্দভাণ্ডার-ব্যবহারের-বিধান" tabindex="-1">3. শব্দভাণ্ডার ব্যবহারের বিধান <a class="header-anchor" href="#_3-শব্দভাণ্ডার-ব্যবহারের-বিধান" aria-label="Permalink to &quot;3. শব্দভাণ্ডার ব্যবহারের বিধান&quot;">​</a></h2><ol><li>এই অভিধানে সংগ্রহ করা শব্দভাণ্ডারগুলো হলো মানক শব্দভাণ্ডার, এবং সমস্ত নথিতে এই অভিধানের মানক প্রকাশকে অগ্রাধিকার দিতে হবে।</li><li>একই ধারণা বিভিন্ন নথিতে অবশ্যই একই শব্দভাণ্ডার ব্যবহার করতে হবে, এবং স্বেচ্ছায় সমার্থক শব্দ পরিবর্তন করা যাবে না।</li><li>নতুন সেটআপে উৎপন্ন নতুন শব্দভাণ্ডার, সময়মতো শব্দভাণ্ডার কমিটিতে জমা দিয়ে পরীক্ষা করাতে হবে, এবং পরীক্ষা পাশ করার পরে এই অভিধানে যোগ করা হবে।</li><li>শব্দভাণ্ডারের সংজ্ঞা যদি সংশোধন হয়, তবে এই অভিধানের সর্বশেষ সংস্করণকে মানদণ্ড হিসেবে গ্রহণ করতে হবে, এবং একই সাথে নথির সংস্করণ ব্যাখ্যায় সংশোধনের বিষয়বস্তু রেকর্ড করতে হবে।</li><li>শব্দভাণ্ডার উদ্ধৃত করার সময়, প্রথমবার পূর্ণ নাম ব্যবহার করা যায়, পরবর্তীতে সংক্ষিপ্ত নাম ব্যবহার করা যায়, কিন্তু প্রসঙ্গের অর্থ স্পষ্ট নিশ্চিত করতে হবে।</li></ol><h2 id="উপসংহার" tabindex="-1">উপসংহার <a class="header-anchor" href="#উপসংহার" aria-label="Permalink to &quot;উপসংহার&quot;">​</a></h2><p>শব্দভাণ্ডার অভিধান হলো সমগ্র সেটআপ সিস্টেমের ভাষাগত ভিত্তিপ্রস্তর। ঐক্যকৃত শব্দভাণ্ডার ব্যবস্থা শত নথির মধ্যে ধারণার ধারাবাহিকতা নিশ্চিত করে, এবং পাঠকদের বিভিন্ন মডিউলের মধ্যে বোঝাপড়ার দ্বন্দ্ব ছাড়াই নিরবচ্ছিন্নভাবে সুইচ করতে সক্ষম করে। সেটআপ সিস্টেমের ক্রমাগত সমৃদ্ধি ও উন্নতির সাথে সাথে, এই অভিধানটি ক্রমাগত আপডেট হবে, এবং সর্বদা সমস্ত নথির শব্দভাণ্ডারের আধিকারিক উৎস হিসেবে থাকবে।</p><h2 id="সম্পর্কিত-নথি" tabindex="-1">সম্পর্কিত নথি <a class="header-anchor" href="#সম্পর্কিত-নথি" aria-label="Permalink to &quot;সম্পর্কিত নথি&quot;">​</a></h2><ul><li>00-Hengyuanzhou মহাজাগতিকের সামগ্রিক ওভারভিউ</li><li>02-অ্যাঙ্কর মূল সংজ্ঞা ও প্রকৃতি</li><li>99-নথির সংস্করণ ও রক্ষণাবেক্ষণ ব্যাখ্যা</li></ul>',12)])])}const c=d(o,[["render",l]]);export{b as __pageData,c as default};
